tool.command:
umask 0000 && export CUDA_CACHE_PATH=/tmp/cuda_cache XDG_CACHE_HOME=/tmp/xdg_cache XDG_CONFIG_HOME=/tmp/xdg_config && export SUBHKL_SHARED_DIR="\${SUBHKL_SHARED_DIR:-/gpfs/neutronsfs/scratch/subhkl_shared}" HDF5_USE_FILE_LOCKING=FALSE && mkdir -p out && chmod 0777 out ;
## Link input files to preserve element_identifier extensions ln -sf "$scan" "$scan.element_identifier" ; ln -sf "$indexer" "$indexer.element_identifier" ;
#set $options = ""
#if $wavelengthMin: #set $options = $options + " --wavel-min " + str($wavelengthMin) + " " #end if #if $wavelengthMax: #set $options = $options + " --wavel-max " + str($wavelengthMax) + " " #end if #if $space: #set $options = $options + " --space-group '" + str($space) + "' " #end if
python -u -m subhkl.io.parser peak-predictor "$scan.element_identifier" $instrument "$indexer.element_identifier" out/peak_predictor.h5 --shared-pointer-out out/peak_predictor_ref.json --d-min $dMin $options && chmod -R a+rwX out
